import React, { useEffect, useState } from "react";
import "./SharedQuiz.css";
import Button from "@mui/joy/Button";
import { useNavigate, useLocation } from "react-router-dom";
import ReactCardFlip from "react-card-flip";
import { Card } from "@mui/joy";
import firebase from "firebase/compat/app";
import "firebase/compat/database";
import firebaseConfig from "./firebaseConfig";

function SharedQuiz() {
  const location = useLocation();
  const searchParams = new URLSearchParams(location.search);
  const num = searchParams.get("num");

  const navigate = useNavigate();
  const [question, setQuestion] = useState("");
  const [answer, setAnswer] = useState("");
  const [isFlipped, setIsFlipped] = useState(false);

  const handleFlipCard = () => {
    setIsFlipped(!isFlipped);
  };

  useEffect(() => {
    // Firebase 초기화
    firebase.initializeApp(firebaseConfig);

    // Firebase Realtime Database에서 num번째 데이터 가져오기
    const database = firebase.database();
    const qaRef = database.ref("QA");

    qaRef.once("value").then((snapshot) => {
      const questions = snapshot.val();
      const questionData = questions[num];
      setQuestion(questionData.que);
      setAnswer(questionData.ans);
    });
  }, [num]);

  const handleShare = (quiz_num) => {
    const share_url = window.location.href + "#/shared-quiz?num=" + quiz_num;
    const share_text = "😉 이런, 퀴즈가 도착했어요 - " + share_url;

    if (navigator.share) {
      navigator
        .share({
          title: "😉 이런, 퀴즈가 도착했어요",
          url: share_url,
        })
        .then(() => {
          console.log("URL 공유 성공");
        })
        .catch((error) => {
          console.error("URL 공유 실패", error);
        });
    } else {
      const dummyInput = document.createElement("input");
      dummyInput.setAttribute("value", share_text);
      document.body.appendChild(dummyInput);
      dummyInput.select();
      document.execCommand("copy");
      document.body.removeChild(dummyInput);
    }
  };

  return (
    <div className="SharedQuiz_Frame">
      <p className="text">
        ☺️친구에게 받은 퀴즈예요☺️
        <br />한 번 맞춰볼까요?
      </p>

      <ReactCardFlip isFlipped={isFlipped} flipDirection="vertical">
        <Card
          sx={{
            height: "180px",
            backgroundColor: "#f2f4fb",
            borderRadius: "8px",
            marginBottom: "30px",
            justifyContent: "center",
            alignItems: "center",
            boxShadow: "0 4px 10px rgba(0, 0, 0, 0.3)", // 그림자 스타일 (크기와 투명도 조정)
            transform: "perspective(600px) rotateY(0)", // 회전을 위한 perspective 설정
            transition: "0.6s", // 애니메이션 전환 시간 설정
            backfaceVisibility: "hidden", // 회전 시 뒷면 숨김
          }}
          className="Card_Front"
          onClick={handleFlipCard}
        >
          <div className="Card_Front_Que">{question}</div>
        </Card>
        <Card
          sx={{
            height: "180px",
            backgroundColor: "#dae1ee",
            borderRadius: "8px",
            marginBottom: "30px",
            justifyContent: "center",
            alignItems: "center",
            boxShadow: "0 4px 10px rgba(0, 0, 0, 0.3)", // 그림자 스타일 (크기와 투명도 조정)
            transform: "perspective(600px) rotateY(0)", // 회전을 위한 perspective 설정
            transition: "0.6s", // 애니메이션 전환 시간 설정
            backfaceVisibility: "hidden", // 회전 시 뒷면 숨김
          }}
          className="Card_Back"
          onClick={handleFlipCard}
        >
          <div className="Card_Back_Ans">{answer}</div>
        </Card>
      </ReactCardFlip>
      <Button
        size="lg"
        className="btn"
        color="info"
        onClick={handleShare}
        variant="solid"
      >
        😎 친구에게 공유하기
      </Button>
      <a href="https://maeun.github.io/hiyoumore/">
        <Button
          style={{ width: "100%" }}
          size="lg"
          className="btn"
          color="info"
          variant="solid"
        >
          📝 다른 퀴즈 풀어보기
        </Button>
      </a>
    </div>
  );
}

export default SharedQuiz;
