import firebase from "firebase/compat/app";
import "firebase/compat/database";
import firebaseConfig from "./firebaseConfig";

import "./Quiz.css";
import React, { useEffect, useState } from "react";
import ReactCardFlip from "react-card-flip";
import { styled } from "@mui/system";

import { Card, Button, IconButton } from "@mui/joy";
import ShareIcon from "@mui/icons-material/Share";
import "react-toastify/dist/ReactToastify.css";

firebase.initializeApp(firebaseConfig);

const ShareButton = styled(Button)(({ theme }) => ({
  backgroundColor: "#FFFFFF",
  borderRadius: "20px",
  padding: theme.spacing(1),
  border: "3px white",
  "&:hover": {
    border: "2px solid pink",
    backgroundColor: "#FF9999",
    color: "#FFFFFF",
  },
  color: "#FF9999", // Change the text color here
}));

function Quiz({ selectedQuestions }) {
  const [isFlipped, setIsFlipped] = useState([]);

  useEffect(() => {
    // 선택한 질문 개수에 따라 isFlipped 배열 초기화
    const initialFlippedState = Array(selectedQuestions.length).fill(false);
    setIsFlipped(initialFlippedState);
  }, [selectedQuestions]);

  const handleClick = (index) => {
    setIsFlipped((prevIsFlipped) => {
      const updatedIsFlipped = [...prevIsFlipped];
      updatedIsFlipped[index] = !updatedIsFlipped[index];
      return updatedIsFlipped;
    });
  };

  if (!selectedQuestions) {
    return <div>문제를 불러오는 중</div>;
  }

  const cardsData = selectedQuestions.map((question) => ({
    frontText: question.que,
    backText: question.ans,
    quiz_num: question.index,
  }));

  const handleShare = (quiz_num) => {
    const share_url = window.location.href + "#/shared-quiz?num=" + quiz_num;
    const share_text = "😉 이런, 퀴즈가 도착했어요 - " + share_url;

    if (navigator.share) {
      navigator
        .share({
          title: "😉 이런, 퀴즈가 도착했어요",
          url: share_url,
        })
        .then(() => {
          console.log("URL 공유 성공");
        })
        .catch((error) => {
          console.error("URL 공유 실패", error);
        });
    } else {
      const dummyInput = document.createElement("input");
      dummyInput.setAttribute("value", share_text);
      document.body.appendChild(dummyInput);
      dummyInput.select();
      document.execCommand("copy");
      document.body.removeChild(dummyInput);
    }
  };

  return (
    <div className="QAcardSet">
      {cardsData.slice(0, 3).map((card, index) => (
        <ReactCardFlip
          key={index}
          isFlipped={isFlipped[index]}
          flipDirection="vertical"
        >
          <Card
            sx={{
              height: "180px",
              backgroundColor: "#f2f4fb",
              borderRadius: "8px",
              marginBottom: "30px",
              justifyContent: "center",
              alignItems: "center",
              boxShadow: "0 4px 10px rgba(0, 0, 0, 0.3)", // 그림자 스타일 (크기와 투명도 조정)
              transform: "perspective(600px) rotateY(0)", // 회전을 위한 perspective 설정
              transition: "0.6s", // 애니메이션 전환 시간 설정
              backfaceVisibility: "hidden", // 회전 시 뒷면 숨김
            }}
            className="Card_Front"
            onClick={() => handleClick(index)}
          >
            <div className="Card_Front_Que">{card.frontText}</div>
          </Card>
          <Card
            sx={{
              height: "180px",
              backgroundColor: "#dae1ee",
              borderRadius: "8px",
              marginBottom: "30px",
              justifyContent: "center",
              alignItems: "center",
              boxShadow: "0 4px 10px rgba(0, 0, 0, 0.3)", // 그림자 스타일 (크기와 투명도 조정)
              transform: "perspective(600px) rotateY(0)", // 회전을 위한 perspective 설정
              transition: "0.6s", // 애니메이션 전환 시간 설정
              backfaceVisibility: "hidden", // 회전 시 뒷면 숨김
            }}
            className="Card_Back"
            onClick={() => handleClick(index)}
          >
            <div className="Card_Back_Ans">{card.backText}</div>
            <ShareButton
              variant="outlined"
              className="ShareButton"
              onClick={() => handleShare(card.quiz_num)}
            >
              친구에게 전달하기 <ShareIcon />
            </ShareButton>
          </Card>
        </ReactCardFlip>
      ))}
    </div>
  );
}

export default Quiz;
